        rows = self.store.active_after(token.after, limit + 1)
        items = rows[:limit]
        next_cursor = None
        if len(rows) > limit:
            last = items[-1]
            next_token = page_token.PageToken(token.offset + len(items), token.top, (last.created_at, last.id))
            next_cursor = page_token.encode(next_token)
        return {"items": [o.to_dict() for o in items], "next_cursor": next_cursor}

